  "magic_text": {
   "anan": "안안은 누군가 한 명(안안 말고)을 세뇌했다. 세뇌당한 사람은 자기도 모르게 틀린 말을 한다. 그 사람은 거짓말쟁이로 세지 않는다.",
   "margo": "마고가 다른 한 사람의 목소리를 흉내 냈을 수도 있다. 그랬다면 그 사람 이름으로 나온 말은 사실 마고의 말이고(맞고 틀림도 마고 몫), 그 사람은 아무 말도 하지 않은 것이다. (흉내 낸 말 속의 \"나\"는 이름이 적힌 사람이다.)",
   "miria": "미리아는 다른 한 사람과 영혼이 뒤바뀌었을 수도 있다. 그랬다면 미리아 이름으로 나온 말은 사실 그 사람이 한 말이고, 그 사람 이름으로 나온 말은 미리아가 한 말이다. 맞고 틀림도, 말 속의 \"나\"도 실제로 말한 사람 몫이다. (\"누구의 말\"은 그 이름으로 나온 말을 뜻한다.)"
  },
